window.DayNotes=[{q:"„Ein Dashboard soll helfen, den Betrieb zu sehen. Es darf nie den eigenen Blick auf den Betrieb ersetzen.“",id:"note-01-dashboard",d:"20. September 2026",iso:"2026-09-20",img:"/media/notes/de/01-dashboard.jpg?v=616cd5e3ca"},{q:"„Wenn ein Problem jeden Tag dieselbe Erinnerung braucht, ist die Erinnerung nicht das System.“",id:"note-02-reminder",d:"20. September 2026",iso:"2026-09-20",img:"/media/notes/de/02-reminder.jpg?v=21ddbe4edf"},{q:"„Verantwortung beginnt dort, wo der Satz ‚Jemand sollte …‘ aufhört.“",id:"note-03-ownership",d:"20. September 2026",iso:"2026-09-20",img:"/media/notes/de/03-ownership.jpg?v=ee402b4ba0"},{q:"„Die Nachtschicht legt schwache Prozesse offen, weil weniger Leute da sind, die sie verdecken.“",id:"note-04-night-shift",d:"20. September 2026",iso:"2026-09-20",img:"/media/notes/de/04-night-shift.jpg?v=ae1abb3dd6"},{q:"„In Excel ist ein Fehler eine Zahl. An der Rampe hat er eine Adresse.“",id:"note-01-excel",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/01-excel.jpg?v=7ae8f16ab4"},{q:"„Eine Kennzahl zeigt Ihnen, wo Sie hinschauen müssen. Was passiert ist, verrät sie allein noch nicht.“",id:"note-02-kpi",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/02-kpi.jpg?v=4531bb9897"},{q:"„Wer nur nach der Zahl führt, kann den Falschen bestrafen.“",id:"note-03-the-number",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/03-the-number.jpg?v=372a03c5fd"},{q:"„Eine aufgeblähte Analyse, die gut aussehen soll, ist gefährlicher als eine unvollständige, die ihre Grenzen offen zugibt.“",id:"note-04-analysis",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/04-analysis.jpg?v=0027dd734d"},{q:"„Klammern Sie sich nicht an den Stuhl, auf dem Sie früher saßen. Nehmen Sie mit, was Sie darauf gelernt haben.“",id:"note-05-the-chair",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/05-the-chair.jpg?v=ce8b1c9b83"},{q:"„Wer die Arbeit macht, sollte nicht nach Informationen suchen müssen. Die Informationen sollten dort sein, wo er sie erwartet.“",id:"note-06-information",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/06-information.jpg?v=be230cb7a3"},{q:"„Ich bin nicht weniger flexibel geworden. Ich bin weniger bereit, Flexibilität an die Stelle des Systems treten zu lassen.“",id:"note-07-flexibility",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/07-flexibility.jpg?v=31cd1287f2"},{q:"„Autorität ohne Titel gewinnt man nicht, indem man sich verhält, als hätte man einen Titel. Man gewinnt sie, indem man nützlich ist.“",id:"note-08-authority",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/08-authority.jpg?v=4c2bea5906"},{q:"„Initiative und Befugnis sind zwei verschiedene Dinge.“",id:"note-09-initiative",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/09-initiative.jpg?v=27e9d928de"},{q:"„Führung heißt nicht, der zu werden, ohne den nichts läuft. Führung heißt, dazu beizutragen, dass es auch läuft, wenn man nicht da ist.“",id:"note-10-leadership",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/10-leadership.jpg?v=a591639349"},{q:"„Tagsüber sieht das Management die Aktivität. Nachts sieht man die Spuren, die sie hinterlassen hat.“",id:"note-11-traces",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/11-traces.jpg?v=91539e3981"},{q:"„Ein Problem, das nicht in die Übergabe kommt, hört nicht auf zu existieren. Es wird nur zum Problem von jemandem, der noch nicht weiß, dass es existiert.“",id:"note-12-handover",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/12-handover.jpg?v=7d8f746f5b"},{q:"„‚Gemeldet‘ und ‚gelöst‘ sind nicht dasselbe.“",id:"note-13-reported",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/13-reported.jpg?v=cac921d681"},{q:"„Ein Team, das Angst hat, seine Fehler zu zeigen, hat nicht weniger Fehler.“",id:"note-14-fear",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/14-fear.jpg?v=f09014f088"},{q:"„Wenn das Ergebnis davon abhängt, dass die richtige Person in der Schicht ist, hat die Organisation Wissen, aber noch keinen Standard.“",id:"note-15-standard",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/15-standard.jpg?v=4b97c255bf"},{q:"„Berichte zeigen mir, wo ich hinschauen muss. Vor Ort sehe ich, was passiert. Ein Manager braucht beides.“",id:"note-16-reports",d:"4. Oktober 2026",iso:"2026-10-04",img:"/media/notes/de/16-reports.jpg?v=ab05aed4e9"},{q:"„Ein Titel kann an einem einzigen Tag verschwinden. Was man gelernt hat, nicht.“",id:"note-17-the-title",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/17-the-title.jpg?v=2ae7990336"},{q:"„Die Tabelle ist der Ausgangspunkt, nicht die Antwort.“",id:"note-18-the-table",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/18-the-table.jpg?v=0331fcfe2c"},{q:"„Bevor man jemanden danach beurteilt, ob er den Standard einhält, muss er ihn kennen.“",id:"note-19-know-the-standard",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/19-know-the-standard.jpg?v=574f95d640"},{q:"„Druck kann berechtigt sein. Menschen zu demütigen ist keine Führungsmethode.“",id:"note-20-pressure",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/20-pressure.jpg?v=b30adc43cf"},{q:"„Wenn derselbe Fehler auch dem Nächsten passieren kann, hat man nicht das System geändert, sondern nur den Namen im Bericht.“",id:"note-21-the-name",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/21-the-name.jpg?v=ecffe4803a"},{q:"„Druck darf nicht als Panik nach unten weitergegeben werden.“",id:"note-22-panic",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/22-panic.jpg?v=58e6ba9d73"},{q:"„Eine Kennzahl verbessert sich, wenn man den Prozess verändert, der sie erzeugt.“",id:"note-23-the-process",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/23-the-process.jpg?v=5a50e11595"},{q:"„Verantwortung heißt nicht, jedes Mal einen Schuldigen zu suchen, wenn eine Zahl rot wird. Sie heißt herauszufinden, wer das Problem verantwortet, und es zu verfolgen, bis es erledigt ist.“",id:"note-24-accountability",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/24-accountability.jpg?v=5c91701a8c"},{q:"„Ob eine SOP taugt, zeigt sich nicht daran, dass ihr Autor sie versteht. Sondern daran, ob ein anderer sie unter Druck anwenden kann und zum selben Ergebnis kommt.“",id:"note-25-the-test",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/25-the-test.jpg?v=4408198311"},{q:"„Wenn die offizielle Version das eine sagt und die Menschen in der Schicht einen anderen Weg gelernt haben, ist die SOP kein Standard mehr.“",id:"note-26-two-versions",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/26-two-versions.jpg?v=07476f1f7b"},{q:"„Ein Problem, das nur eine Person kennt, ist trotzdem ein Problem der Organisation. Wenn es dokumentiert ist, kann es einen Verantwortlichen bekommen.“",id:"note-27-written-down",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/27-written-down.jpg?v=a02c636276"},{q:"„Viele Fehler entstehen nicht aus fehlendem Können. Sie entstehen aus dem Satz: ‚Machen wir später.‘“",id:"note-28-later",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/28-later.jpg?v=0d971f0555"},{q:"„Einmal kann ein Fehler Zufall sein. Derselbe Fehler mehrmals ist ein Prozess.“",id:"note-29-twice",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/29-twice.jpg?v=cbe6a47355"},{q:"„Eine Übergabe ist nicht nur eine Weitergabe von Information. Sie ist eine Weitergabe von Verantwortung.“",id:"note-30-responsibility",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/30-responsibility.jpg?v=4e30935aee"},{q:"„Wer ständig die Lücken eines Systems stopft, erweckt den Eindruck, dass das System funktioniert. Weil es immer jemand rettet.“",id:"note-31-the-gaps",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/31-the-gaps.jpg?v=1c6f547adc"},{q:"„Standardisierung soll den Menschen nicht das Denken abnehmen. Sie soll verhindern, dass sie Dinge neu erfinden müssen, die die Organisation schon wissen sollte.“",id:"note-32-reinvent",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/32-reinvent.jpg?v=4434bf81ff"},{q:"„Die Daten müssen mich dorthin führen, wo gearbeitet wird. Und was ich dort sehe, muss mir helfen, die Daten zu verstehen.“",id:"note-33-the-floor",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/33-the-floor.jpg?v=2926969354"},{q:"„In den ersten 30 Tagen braucht eine neue Führungskraft keine 30 Lösungen. Sie braucht 30 gute Fragen.“",id:"note-34-thirty-questions",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/34-thirty-questions.jpg?v=957c105174"},{q:"„Ein Schritt, der überflüssig wirkt, kann der Schritt sein, von dem jemand anderes abhängt.“",id:"note-35-dependencies",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/35-dependencies.jpg?v=3d2dfe3b9d"},{q:"„Das Problem war nicht fehlende Information. Das Problem war, dass sie nicht schnell zeigte, wo man steht und was als Nächstes kommt.“",id:"note-36-scattered",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/36-scattered.jpg?v=6229bc6a1b"},{q:"„Die Übergabe zeigt, welchen Zustand Sie übernehmen. Das Briefing entscheidet, was jetzt zählt.“",id:"note-37-inherit-decide",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/37-inherit-decide.jpg?v=6474ac3850"},{q:"„Wenn Sie nur die Zahl nennen und die Schicht beginnt, haben Sie Information gegeben, keine Richtung.“",id:"note-38-direction",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/38-direction.jpg?v=f22cff0b41"},{q:"„Ein Briefing ergibt Sinn, wenn aus einer Kennzahl ein klares Verhalten oder eine klare Handlung wird.“",id:"note-39-kpi-to-action",d:"5. Oktober 2026",iso:"2026-10-05",img:"/media/notes/de/39-kpi-to-action.jpg?v=ddbc48360f"},{q:"„Wenn der Standard der Einarbeitung ‚Schau, wie ich es mache‘ lautet, bekommt jeder neue Mitarbeiter eine andere Version derselben Arbeit.“",id:"note-40-versions",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/40-versions.jpg?v=c348c3b132"},{q:"„‚Ja, verstanden‘ ist kein Beweis. Machen Sie es selbst. Erklären Sie mir, warum. Zeigen Sie mir, was Sie tun, wenn eine Ausnahme kommt.“",id:"note-41-proof",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/41-proof.jpg?v=f124f81046"},{q:"„Eine Einarbeitung misst sich nicht daran, wie gut der Trainer erklärt hat. Sondern daran, wie einheitlich das Ergebnis wird, wenn er geht.“",id:"note-42-trainer-leaves",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/42-trainer-leaves.jpg?v=6a0871ff8a"},{q:"„Ein gutes Eskalationssystem bringt Menschen nicht bei, für alles um Erlaubnis zu fragen. Es bringt ihnen bei, zu erkennen, wo ihre eigene Entscheidung endet.“",id:"note-43-decision-limit",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/43-decision-limit.jpg?v=4bf3d9cec9"},{q:"„Eskalieren Sie die Entscheidung, nicht die Unklarheit, die Sie selbst hätten klären können.“",id:"note-44-escalate-the-decision",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/44-escalate-the-decision.jpg?v=ce0b5d3b59"},{q:"„Verantwortung übernehmen heißt nicht, alles selbst zu lösen. Es heißt, das Problem mit den richtigen Informationen dorthin zu bringen, wo richtig entschieden werden kann.“",id:"note-45-ownership",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/45-ownership.jpg?v=00ae50c290"},{q:"„Der Ort, an dem ein Fehler gemessen wird, ist nicht unbedingt der Ort, an dem er entstanden ist.“",id:"note-46-measured-born",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/46-measured-born.jpg?v=cc115f24c0"},{q:"„Gesendete Information ist nicht immer empfangene Information. Und ein gemeldetes Problem ist nicht unbedingt ein gelöstes.“",id:"note-47-sent-received",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/47-sent-received.jpg?v=0dd330e040"},{q:"„Ein Prozess endet nicht, wenn ich die Arbeit übergebe. Er endet, wenn das nächste Team weitermachen kann, ohne etwas zu verlieren.“",id:"note-48-process-ends",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/48-process-ends.jpg?v=86c5924320"},{q:"„Eine Kennzahl kann mathematisch richtig sein und trotzdem unfair gelesen werden.“",id:"note-49-correct-unfair",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/49-correct-unfair.jpg?v=d2ead0dc88"},{q:"„Aufgabe der Führungskraft ist es, zu trennen, was die Person selbst in der Hand hat und was im System korrigiert werden muss.“",id:"note-50-person-system",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/50-person-system.jpg?v=efd01c1795"},{q:"„Eine Zahl zeigt das Ergebnis, die andere den Grund. Ohne die zweite werden Zahlen zu Berichten ohne Lernen.“",id:"note-51-result-reason",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/51-result-reason.jpg?v=c459d6e7e0"},{q:"„Druck kann fair sein. Demütigung nicht.“",id:"note-52-pressure",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/52-pressure.jpg?v=5b62085f09"},{q:"„Formale Befugnis gibt das Recht, Entscheidungen zu treffen. Vertrauen entsteht durch die Art, wie man sie trifft.“",id:"note-53-authority-trust",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/53-authority-trust.jpg?v=bffb607d60"},{q:"„Ein Fehler sollte zu zwei Fragen führen: Was hat im Prozess nicht funktioniert, und welche Verantwortung hatte die Person?“",id:"note-54-two-questions",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/54-two-questions.jpg?v=f15298d60a"},{q:"„Eine Sprache noch nicht gut zu sprechen heißt nicht, dass man seine Arbeit nicht gut macht.“",id:"note-55-language-ability",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/55-language-ability.jpg?v=dda55c52ff"},{q:"„‚Verstanden?‘ reicht nicht immer. ‚Zeig mir, wie du es machen würdest‘ schon.“",id:"note-56-show-me",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/56-show-me.jpg?v=fd0e489932"},{q:"„Ein guter Standard misst sich daran, wie genau verschiedene Menschen ihn umsetzen, auch ohne gemeinsame Sprache.“",id:"note-57-standard-measured",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/57-standard-measured.jpg?v=42503a6d35"},{q:"„Nach dem Verfahren suchen, nicht nach dem Dokument.“",id:"note-58-search-procedure",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/58-search-procedure.jpg?v=0c90e59b65"},{q:"„Man kann zeigen, wie man Informationen ordnet, ohne die sensiblen Informationen zu veröffentlichen, auf denen die Arbeit beruht.“",id:"note-59-method-not-data",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/59-method-not-data.jpg?v=487fba856a"},{q:"„Eine SOP wird nützlich, wenn derjenige, der sie braucht, sie im richtigen Moment finden, verstehen und anwenden kann.“",id:"note-60-sop-useful",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/60-sop-useful.jpg?v=f2c86095ec"},{q:"„Ein Partner wird nicht wie ein Mitarbeiter geführt. Er braucht einen Grund, weiter mit Ihnen zusammenzuarbeiten.“",id:"note-61-partner",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/61-partner.jpg?v=5bce121cbb"},{q:"„Befugnis kann helfen, eine Entscheidung zu treffen. Vertrauen sorgt dafür, dass die Zusammenarbeit weitergeht.“",id:"note-62-authority-trust",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/62-authority-trust.jpg?v=ac995673bb"},{q:"„Das Ziel ist kein Team, das ohne mich nicht arbeiten kann, sondern eine Arbeitsweise, die weiterläuft, wenn ich nicht da bin.“",id:"note-63-runs-without-me",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/63-runs-without-me.jpg?v=386df4e367"},{q:"„Das Dokument sagt, wie die Arbeit sein soll. Die Menschen zeigen, wie sie ist.“",id:"note-64-document-people",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/64-document-people.jpg?v=7d8d2c7444"},{q:"„Kommen Sie, um zu verstehen, nicht um zu zeigen, wie viel Sie wissen.“",id:"note-65-walk-in",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/65-walk-in.jpg?v=496ae53972"},{q:"„Verändern Sie nichts nur, um zu zeigen, dass Sie gekommen sind, um Veränderung zu bringen.“",id:"note-66-change-to-show",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/66-change-to-show.jpg?v=4df60b2500"},{q:"„Die ersten Tage eines Neuen sind eine Informationsquelle, die die meisten Organisationen verschenken.“",id:"note-67-new-eyes",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/67-new-eyes.jpg?v=205201153a"},{q:"„Eine Aufgabe ohne Verantwortlichen ist so gut wie eine Aufgabe, die niemand erledigt.“",id:"note-68-no-owner",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/68-no-owner.jpg?v=c72d56edfb"},{q:"„Ein gutes Briefing misst sich nicht daran, wie viel gesagt wurde, sondern daran, was das Team in der ersten Stunde anders macht.“",id:"note-69-first-hour",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/69-first-hour.jpg?v=7ce7e69a8c"},{q:"„Informationen liefern Ihnen die Einzelteile. Ein System liefert die Reihenfolge, den Grund und den Punkt, an dem Sie wissen, dass Sie allein weitermachen können.“",id:"note-70-pieces-order",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/70-pieces-order.jpg?v=5402e47778"},{q:"„Ohne eine SOP, die tatsächlich genutzt wird, wird Einarbeitung zum Abschauen.“",id:"note-71-copying",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/71-copying.jpg?v=0e00cef0bb"},{q:"„Initiative ergibt Sinn innerhalb der Grenze, die man kennt. Jenseits davon ist Improvisieren kein Mut. Es ist Risiko.“",id:"note-72-improvising",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/72-improvising.jpg?v=2bce9f0963"},{q:"„Ein Betrieb, der davon abhängt, wer Schicht hatte, ist noch kein Betrieb, der ohne Sie läuft.“",id:"note-73-who-was-on-shift",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/73-who-was-on-shift.jpg?v=e2913e6b89"},{q:"„Eine vollständige Eskalation, die zu spät kommt, ist schlechter als eine kurze, die rechtzeitig kommt.“",id:"note-74-late-escalation",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/74-late-escalation.jpg?v=5065fb4d08"},{q:"„Eine Abteilung kann ihre Arbeit sehr gut machen, und der Betrieb kann trotzdem scheitern.“",id:"note-75-between-departments",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/75-between-departments.jpg?v=0455a7fe68"},{q:"„Die Zahl zeigt, wo man das Problem suchen muss, nicht, wer es verursacht hat.“",id:"note-76-where-not-who",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/76-where-not-who.jpg?v=27a70ae30d"},{q:"„Eine Kennzahl, der das Team vertraut, ist nicht die, die immer grün ist, sondern die, die klar misst und fair gelesen wird.“",id:"note-77-not-always-green",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/77-not-always-green.jpg?v=15022cbe85"},{q:"„Wer das Gespräch mit der Verantwortung beginnt, hat geurteilt, bevor er zugehört hat.“",id:"note-78-judged-before-listening",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/78-judged-before-listening.jpg?v=7a139316fe"},{q:"„Ein unklarer Standard bleibt unklar, in welche Sprache man ihn auch übersetzt.“",id:"note-79-unclear-any-language",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/79-unclear-any-language.jpg?v=845d8d3a74"},{q:"„Wenn jemand eine Anweisung nicht versteht, endet unsere Aufgabe nicht damit, denselben Satz lauter zu wiederholen.“",id:"note-80-louder",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/80-louder.jpg?v=4310f6ce78"},{q:"„Dass ich eine Anleitung verstehe, heißt nicht, dass jemand, der sie zum ersten Mal sieht, sie genauso versteht.“",id:"note-81-first-time-reader",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/81-first-time-reader.jpg?v=6d1d52ff2a"},{q:"„Es ist besser, eine Grenze rechtzeitig zu erklären, als eine Erwartung zu wecken, die man nicht erfüllen kann.“",id:"note-82-explain-a-limit",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/82-explain-a-limit.jpg?v=fc30480f02"},{q:"„Der Wert einer Führungskraft liegt nicht darin, wie viel durch ihre Hände geht, sondern darin, wie gut es weiterläuft, wenn nichts mehr durch sie geht.“",id:"note-83-through-his-hands",d:"8. Oktober 2026",iso:"2026-10-08",img:"/media/notes/de/83-through-his-hands.jpg?v=e45dced67e"},{q:"„Wie lösen wir es, warum ist es passiert, und was ändern wir, damit es nicht wiederkommt?“",id:"note-84-why-did-it-happen",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/84-why-did-it-happen.jpg?v=ac453053a8"},{q:"„Die zehn Minuten vor der Schicht sind nicht dafür da, alles zu erzählen, was wir wissen. Sie sind dafür da, zu entscheiden, was das Team wissen muss, bevor die Arbeit beginnt.“",id:"note-85-ten-minutes",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/85-ten-minutes.jpg?v=6e555a5ae9"},{q:"„Habe ich einen Betrieb aufgebaut, der als System funktioniert, oder einen Betrieb, der von meiner Anwesenheit abhängt?“",id:"note-86-system-or-presence",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/86-system-or-presence.jpg?v=1d31e4807a"},{q:"„An welchem Punkt ist die Arbeit in andere Hände übergegangen, und welche Information ist bei diesem Übergang verloren gegangen?“",id:"note-87-changed-hands",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/87-changed-hands.jpg?v=b1237a3279"},{q:"„Schauen Sie zu. Machen Sie es mit mir. Machen Sie es selbst, während ich zuschaue. Machen Sie es allein. Dann erklären Sie es mir.“",id:"note-88-watch-do-explain",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/88-watch-do-explain.jpg?v=fe9d3d9d57"},{q:"„Ich ignoriere es nicht, nur weil ‚es nicht meins ist‘.“",id:"note-89-not-mine",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/89-not-mine.jpg?v=6dd8a4acae"},{q:"„Gute Führung heißt, beides zu sehen, ohne um jeden Preis einen Schuldigen zu suchen und ohne Verantwortung zu verstecken, wenn es sie gibt.“",id:"note-90-see-both",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/90-see-both.jpg?v=a4b18cbcf9"},{q:"„Eine Kennzahl zeigt Ihnen, dass Sie ein Problem haben. Sie zeigt nicht automatisch, wo es angefangen hat und wer es verursacht hat.“",id:"note-91-kpi-tells-problem",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/91-kpi-tells-problem.jpg?v=24aa3a2086"},{q:"„Schadensmanagement darf nicht nur der Versuch sein, die Quote im Bericht zu senken. Es muss der Versuch sein, Schäden im Prozess zu verstehen und zu verhindern.“",id:"note-92-managing-damage-should",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/92-managing-damage-should.jpg?v=bf0f9a8457"},{q:"„Das Ziel ist nicht eine niedrigere Quote im Bericht. Es ist ein Schaden weniger im Prozess.“",id:"note-93-goal-lower-percentage",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/93-goal-lower-percentage.jpg?v=dee4316312"},{q:"„Eine Bestellung kann unvollständig beim Kunden ankommen, aber das Problem kann lange vor der Zustellung begonnen haben.“",id:"note-94-order-reach-customer",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/94-order-reach-customer.jpg?v=d350b3d894"},{q:"„Die Unvollständigkeitsquote darf nicht nur als negative Zahl oder als Fehler des Fahrers gesehen werden. Sie soll uns helfen zu verstehen, wo das Produkt oder die Information verloren gegangen ist und wie wir verhindern, dass es wieder passiert.“",id:"note-95-incomplete-should-seen",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/95-incomplete-should-seen.jpg?v=08cbbb8b59"},{q:"„Die beste Kontrolle ist nicht die, die unvollständige Bestellungen zählt, sondern die, die sie stoppt, bevor sie losfahren.“",id:"note-96-best-check-one",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/96-best-check-one.jpg?v=a0e7ca4b25"},{q:"„Gemba darf kein Kontrollgang sein. Es soll ein Weg sein, den Prozess zu verstehen, den Menschen zuzuhören und die Hindernisse zu finden, die die Zahlen nicht erklären.“",id:"note-97-gemba-should-inspection",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/97-gemba-should-inspection.jpg?v=cd8510c57a"},{q:"„Eine Führungskraft, die nur den Bericht sieht, kennt das Ergebnis der Arbeit. Eine Führungskraft, die auch dorthin geht, wo gearbeitet wird, hat die Chance zu verstehen, wie dieses Ergebnis entsteht.“",id:"note-98-manager-who-only",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/98-manager-who-only.jpg?v=b85b58bc0c"},{q:"„Eine organisierte Rampe ist nicht nur sauberer. Sie macht das Verladen übersichtlicher, Fehler fallen früher auf, und die Menschen arbeiten unter sichereren Bedingungen.“",id:"note-99-organised-ramp-cleaner",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/99-organised-ramp-cleaner.jpg?v=c8a215fcd7"},{q:"„Ordnung beweist sich nicht durch ein Plakat an der Wand. Sie beweist sich daran, wie der Arbeitsplatz an einem harten Tag läuft.“",id:"note-100-order-proved-by",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/100-order-proved-by.jpg?v=95a0822d76"},{q:"„6S darf nichts sein, was man vor einer Kontrolle macht. Es muss Teil der täglichen Arbeitsweise sein.“",id:"note-101-6s-should-something",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/101-6s-should-something.jpg?v=84f064913e"},{q:"„Wenn wir die Regeln nach jeder Schwankung ändern, riskieren wir mehr Instabilität als Verbesserung.“",id:"note-102-if-change-rules",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/102-if-change-rules.jpg?v=745d663132"},{q:"„Eine Führungskraft muss wissen, wann sie sofort eingreift und wann sie mehr Informationen sammelt.“",id:"note-103-manager-know-when",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/103-manager-know-when.jpg?v=9537f52dc8"},{q:"„Die Kennzahl zeigt, was passiert ist. Der Trend hilft zu verstehen, ob sich etwas verändert. Die Analyse des Prozesses hilft zu entscheiden, was zu tun ist.“",id:"note-104-kpi-shows-happened",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/104-kpi-shows-happened.jpg?v=166e5a65e1"},{q:"„Ein schlechter Tag ist ein Signal zum Prüfen. Er ist nicht automatisch der Beweis, dass der ganze Prozess geändert werden muss.“",id:"note-105-bad-day-signal",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/105-bad-day-signal.jpg?v=51d49208ed"},{q:"„Der Wert von DMAIC liegt in der Disziplin, nicht sofort vom Problem zur Lösung zu springen.“",id:"note-106-value-dmaic-lies",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/106-value-dmaic-lies.jpg?v=401859628c"},{q:"„Ein Problem ist nicht gelöst, nur weil es heute nicht wieder aufgetreten ist.“",id:"note-107-problem-solved-happen",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/107-problem-solved-happen.jpg?v=587c430aa3"},{q:"„Wenn man das Fahrzeug nicht sieht, braucht man einen verlässlichen Weg zu verstehen, was mit ihm passiert.“",id:"note-108-when-cannot-see",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/108-when-cannot-see.jpg?v=d80c68343f"},{q:"„Remote-Koordination heißt nicht einfach, den Fahrern Anweisungen zu geben. Es heißt, eine Art der Kommunikation aufzubauen, in der Probleme sichtbar werden, Verantwortung klar ist und Entscheidungen rechtzeitig getroffen werden.“",id:"note-109-remote-coordination-giving",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/109-remote-coordination-giving.jpg?v=6f2d7c4f22"},{q:"„Druck erzeugt nicht immer die Probleme. Oft macht er sie sichtbarer.“",id:"note-110-pressure-always-create",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/110-pressure-always-create.jpg?v=328811c3da"},{q:"„Kapazität ist nicht nur die Zahl der Menschen, die man zur Verfügung hat, sondern die Zahl derer, die die Arbeit nach Standard machen können.“",id:"note-111-capacity-number-people",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/111-capacity-number-people.jpg?v=ce82bc5026"},{q:"„Der Standard beweist sich nicht an dem Tag, an dem alles nach Plan läuft. Er beweist sich an dem Tag, an dem der Plan nicht reicht.“",id:"note-112-standard-proved-day",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/112-standard-proved-day.jpg?v=9d483a906a"},{q:"„Nachts sind die Möglichkeiten für eine Lösung nicht immer dieselben wie am Tag. Aber das heißt nicht, dass die Verantwortung für das Problem verloren gehen darf.“",id:"note-113-night-options-solution",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/113-night-options-solution.jpg?v=682473504a"},{q:"„Eine Beschwerde ist nicht erledigt, nur weil der Gast die Rezeption verlässt.“",id:"note-114-complaint-closed-guest",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/114-complaint-closed-guest.jpg?v=b18497a3d7"},{q:"„Professionalität heißt zuhören, prüfen, tun, was in der eigenen Zuständigkeit liegt, und dafür sorgen, dass die Arbeit weitergeht, wenn jemand anderes einbezogen werden muss.“",id:"note-115-professionalism-listening-checking",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/115-professionalism-listening-checking.jpg?v=c1d03066a8"},{q:"„Der Gast sollte nicht mit Zeit und Nerven dafür bezahlen, dass das Hotel in Schichten arbeitet.“",id:"note-116-guest-should-pay",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/116-guest-should-pay.jpg?v=a240774362"},{q:"„Ein Standard, der nur in einem Dokument existiert, ist nicht unbedingt ein Standard, der angewendet wird.“",id:"note-117-standard-exists-only",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/117-standard-exists-only.jpg?v=08bd8f3540"},{q:"„Haben wir eine Verbesserung geschaffen, die Teil des Systems wird, oder ein vorübergehendes Ergebnis, das von der Aufmerksamkeit der Führungskraft abhängt?“",id:"note-118-built-improvement-becomes",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/118-built-improvement-becomes.jpg?v=77d9bca8ed"},{q:"„Echte Verbesserung funktioniert nicht nur, solange die Führungskraft da ist. Sie funktioniert weiter, wenn die Führungskraft geht.“",id:"note-119-real-improvement-kind",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/119-real-improvement-kind.jpg?v=82f80a45d7"},{q:"„Eine gute Führungskraft kann einen Arbeitstag verbessern. Ein gutes System hält die Verbesserung auch an dem Tag am Leben, an dem die Führungskraft nicht da ist.“",id:"note-120-good-manager-improve",d:"10. Oktober 2026",iso:"2026-10-10",img:"/media/notes/de/120-good-manager-improve.jpg?v=f6f9e57f2e"},{q:"„Die Branche ändert sich. Was man kontrolliert, ändert sich. Aber das Problem der Führung bleibt dasselbe: Wenn Information, Verantwortung und Ausführung nicht an derselben Stelle zusammenkommen, taucht irgendwo ein Fehler auf.“",id:"note-121-industry-changes-problem",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/121-industry-changes-problem.jpg?v=23c47b2f55"},{q:"„Den Kunden interessiert kaum, welche Abteilung den Fehler gemacht hat. Er sieht nur das Unternehmen vor sich.“",id:"note-122-customer-sees-company",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/122-customer-sees-company.jpg?v=ce6a9821e0"},{q:"„Führung bedeutet nicht immer, Autorität über jemanden zu haben. Oft bedeutet sie, Menschen, über die man keine Autorität hat, dazu zu bringen, in dieselbe Richtung zu arbeiten wie man selbst.“",id:"note-123-without-authority-direction",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/123-without-authority-direction.jpg?v=3b3fd35d97"},{q:"„Die Branche kann man lernen. Schwerer zu lernen ist, zu erkennen, wann ein Prozess nicht funktioniert, nicht am Problem vorbeizugehen, sondern sich seiner anzunehmen und es zu Ende zu bringen.“",id:"note-124-learn-the-industry",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/124-learn-the-industry.jpg?v=263c9da54f"},{q:"„Erwarten Sie im neuen Job nicht, dass andere respektieren, was Sie einmal waren. Fangen Sie an zu zeigen, was Sie dort können, wo Sie jetzt sind.“",id:"note-125-show-what-you-can",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/125-show-what-you-can.jpg?v=a172cbbea1"},{q:"„Hätte ich manche Jobs für unter meiner Würde gehalten, hätte ich vielleicht nie gelernt, was ich brauchte, um wieder aufzusteigen.“",id:"note-126-jobs-beneath-me",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/126-jobs-beneath-me.jpg?v=0f517cad29"},{q:"„Vor Ort sieht man nicht nur zu. Man rekonstruiert, was passiert ist.“",id:"note-127-floor-reconstruct",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/127-floor-reconstruct.jpg?v=2f67279b53"},{q:"„Was man sieht, muss festgehalten werden, sonst ist es morgen nur eine Erinnerung.“",id:"note-128-written-down-memory",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/128-written-down-memory.jpg?v=33721f0c1f"},{q:"„Respekt heißt nicht, niemanden zur Verantwortung zu ziehen. Respekt heißt, einem Menschen den Standard klarzumachen, ihm zuzuhören, bevor man urteilt, und, wenn die Verantwortung bei ihm liegt, ihm das nicht zu verschweigen.“",id:"note-129-respect-accountable",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/129-respect-accountable.jpg?v=48db6390d4"},{q:"„Ein Standard kann sehr streng sein, ohne den Menschen wie eine Zahl zu behandeln.“",id:"note-130-standard-strong-number",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/130-standard-strong-number.jpg?v=a8cfb7df4f"},{q:"„Pareto liefert nicht die Wahrheit, wenn die Daten, die hineingehen, sie nicht abbilden.“",id:"note-131-pareto-truth",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/131-pareto-truth.jpg?v=dd0afc23ee"},{q:"„Wenn eine Analyse als einzige Antwort ‚Der Mitarbeiter war unachtsam‘ liefert, hat sie sehr oft zu früh aufgehört.“",id:"note-132-analysis-ended-early",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/132-analysis-ended-early.jpg?v=61ad8c380b"},{q:"„Wenn ein Prozess nur funktioniert, weil ein guter Mitarbeiter ihn im Kopf hat, hat man noch keinen guten Prozess.“",id:"note-133-good-person-remembers",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/133-good-person-remembers.jpg?v=0c998486e3"},{q:"„Der Prozess ist wichtig, aber Menschen sind keine Prozesse. Ein Mitarbeiter kann dieselbe Aufgabe haben wie gestern und heute in einer ganz anderen Verfassung zur Arbeit kommen.“",id:"note-134-people-not-processes",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/134-people-not-processes.jpg?v=976a2c25be"},{q:"„Wenn ein Prozess funktionierte, weil ich ihn kannte, würde ich heute versuchen, dafür zu sorgen, dass das System ihn kennt.“",id:"note-135-system-know-it",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/135-system-know-it.jpg?v=2960f0f2c1"},{q:"„Eine Nachricht, die drei Rückfragen braucht, um verstanden zu werden, hat die Zeit verloren, die sie sparen sollte.“",id:"note-136-message-follow-up",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/136-message-follow-up.jpg?v=57aea3c680"},{q:"„Eine Verspätung ist ein Ereignis. Dieselbe Verspätung, am selben Ort, mehrere Tage hintereinander, ist ein Muster.“",id:"note-137-delay-pattern",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/137-delay-pattern.jpg?v=c54d62b7d9"},{q:"„An der Rampe steht das Problem vor einem. Aus der Ferne sucht man es entweder, oder man hat dafür gesorgt, dass es von selbst zu einem kommt.“",id:"note-138-come-to-you",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/138-come-to-you.jpg?v=ccf51d7bba"},{q:"„Man braucht kein Black-Belt-Zertifikat, um gute Fragen zu stellen. Aber es reicht auch nicht, den Namen einer Methode zu kennen, um zu behaupten, man habe sie angewendet.“",id:"note-139-name-of-method",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/139-name-of-method.jpg?v=46ce38ae8a"},{q:"„Wenn eine Verbesserung nur hält, solange eine bestimmte Person da ist, war es keine Verbesserung des Prozesses. Es war die Anwesenheit einer Person.“",id:"note-140-one-persons-presence",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/140-one-persons-presence.jpg?v=33a7f2b0f5"},{q:"„Ein Prozess, der kontrolliert wird, verhält sich anders, solange die Führungskraft da ist.“",id:"note-141-inspected-behaves",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/141-inspected-behaves.jpg?v=286f903723"},{q:"„Jemand sieht das Problem, fragt nach, und die Frage bleibt unbeantwortet. Am nächsten Tag ist das Problem noch da, aber jetzt sieht es normal aus.“",id:"note-142-looks-normal",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/142-looks-normal.jpg?v=1443015d65"},{q:"„Eine SOP, die nur gelesen wird, kann sehr professionell aussehen. Aber wenn der Druck der Schicht beginnt, hat niemand Zeit, ein Handbuch zu lesen.“",id:"note-143-manual-pressure",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/143-manual-pressure.jpg?v=250587810a"},{q:"„Ein Dokument sagt einem, wie die Arbeit gemacht werden soll. Eine gute SOP hilft einem, die Arbeit genau in dem Moment richtig zu machen, in dem man sie braucht.“",id:"note-144-sop-right-moment",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/144-sop-right-moment.jpg?v=ad9ba233ef"},{q:"„Eine Nachtschicht endet nicht, wenn das System abgeschlossen ist. Sie endet, wenn die Person nach mir klar versteht, was passiert ist, was gelöst wurde und was noch weiterverfolgt werden muss.“",id:"note-145-night-shift-ends",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/145-night-shift-ends.jpg?v=03459814f3"},{q:"„Verantwortung heißt nicht, jede Entscheidung zu treffen. Verantwortung heißt zu wissen, welche Entscheidung man selbst treffen kann und welche man nicht treffen sollte.“",id:"note-146-which-decision",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/146-which-decision.jpg?v=23da762247"},{q:"„Ein guter Bericht soll nicht nur die Vergangenheit beschreiben. Er soll den Tag, der beginnt, sicherer machen.“",id:"note-147-report-safer",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/147-report-safer.jpg?v=784e292524"},{q:"„Ich wollte mir nicht merken müssen, wo jedes Dokument liegt. Ich wollte wissen, wo ich die richtige Antwort finde.“",id:"note-148-where-to-go",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/148-where-to-go.jpg?v=552e29d22d"},{q:"„Eine Führungskraft kann fordernd, entschlossen und sehr klar sein, ohne die Würde des Menschen zu verletzen, der vor ihr steht.“",id:"note-149-demanding-dignity",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/149-demanding-dignity.jpg?v=6004f5f9d9"},{q:"„Das Ziel des Gesprächs nach einem Fehler ist nicht, dass der Mitarbeiter mit Angst vor dem nächsten hinausgeht. Sondern dass er hinausgeht und weiß, was er anders machen soll.“",id:"note-150-leave-knowing",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/150-leave-knowing.jpg?v=07c91336f4"},{q:"„Wenn alles seinen Platz hat, fällt auf, was nicht an seinem Platz ist. Wenn nichts einen festen Platz hat, wirkt nichts fehl am Platz.“",id:"note-151-out-of-place",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/151-out-of-place.jpg?v=9a733e6c94"},{q:"„Sicherheit ist nicht das letzte S, das der Liste angehängt wird. Sie ist der Grund, warum es die Liste gibt.“",id:"note-152-reason-list-exists",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/152-reason-list-exists.jpg?v=7b535d2083"},{q:"„Ein aufgeräumter Bereich mit einem offenen Problem, von dem niemand weiß, ist kein aufgeräumter Bereich.“",id:"note-153-tidy-area",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/153-tidy-area.jpg?v=76c86fd39f"},{q:"„Ein Plan, der nur funktioniert, wenn alles wie vorhergesagt läuft, ist kein Plan für den schweren Tag. Er ist die Beschreibung eines gewöhnlichen.“",id:"note-154-ordinary-day-plan",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/154-ordinary-day-plan.jpg?v=62c1b4e8a6"},{q:"„Am schweren Tag wird etwas verschoben. Die Frage ist, ob Sie vorher entschieden haben, was nie verschoben wird, oder ob Sie es mitten unter Druck entscheiden.“",id:"note-155-never-pushed-back",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/155-never-pushed-back.jpg?v=d458856e30"},{q:"„Ein Standard, der nur eingehalten werden kann, wenn Zeit übrig ist, ist kein Standard. Er ist ein Wunsch.“",id:"note-156-standard-wish",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/156-standard-wish.jpg?v=acfc4efe3e"},{q:"„Eine Verbesserung, die von der Aufmerksamkeit der Führungskraft abhängt, hält so lange wie die Aufmerksamkeit.“",id:"note-157-attention-lasts",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/157-attention-lasts.jpg?v=4d682181fe"},{q:"„Die Quote sagt Ihnen, wie viel. Die Fragen sagen Ihnen, wo. Und beim ‚Wo‘ beginnt die Änderung.“",id:"note-158-only-where-changed",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/158-only-where-changed.jpg?v=7cace2956d"},{q:"„An der Tür des Kunden ist eine fehlende Tasche eine Beschwerde. An der Rampe ist sie noch eine Frage.“",id:"note-159-still-a-question",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/159-still-a-question.jpg?v=febc7f1c86"},{q:"„Ein Standard sagt nicht nur, was gemacht wird. Er sagt auch, wo.“",id:"note-160-also-says-where",d:"12. Oktober 2026",iso:"2026-10-12",img:"/media/notes/de/160-also-says-where.jpg?v=3359f02f03"},{q:"„Das System ist schneller als Sie in allem, was man ihm gesagt hat. Es weiß nichts von dem, was man ihm nicht gesagt hat. Und das meiste, was man vor Ort weiß, hat nie jemand irgendwem gesagt.“",id:"note-161-system-faster-than",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/161-system-faster-than.jpg?v=8983a1d66b"},{q:"„Das System entscheidet zuerst. Ihnen bleibt der Teil, den man ihm nie gesagt hat, und die Verantwortung für alles.“",id:"note-162-system-decides-first",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/162-system-decides-first.jpg?v=d0e3aa0fcd"},{q:"„Verwechseln Sie den Verlust des Titels nicht mit dem Verlust Ihres beruflichen Werts.“",id:"note-163-confuse-losing-title",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/163-confuse-losing-title.jpg?v=5eef704aff"},{q:"„Eine solche Regel wirkt auf dem Papier klein. An der Rampe ist sie der Unterschied zwischen einem Problem, das rechtzeitig erkannt wird, und einem Kunden, der eine unvollständige Bestellung erhält.“",id:"note-164-rule-like-looks",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/164-rule-like-looks.jpg?v=5a7b73ef85"},{q:"„Der Standard war kein Poster an der Wand. Zu ihm gehörten Erwartungen, Kontrollen und Verantwortung.“",id:"note-165-standard-was-poster",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/165-standard-was-poster.jpg?v=de786fcf58"},{q:"„Die falsche Kategorie führt einen mit großer Sicherheit zur falschen Ursache.“",id:"note-166-wrong-category-leads",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/166-wrong-category-leads.jpg?v=eb2d88455b"},{q:"„Mehr Verantwortung zu übernehmen heißt nicht, Entscheidungen zu treffen, die einem nicht zustehen.“",id:"note-167-taking-more-responsibility",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/167-taking-more-responsibility.jpg?v=ab27fa52c7"},{q:"„Berufsbezeichnungen ändern sich schneller als die menschliche Natur. Druck, Missverständnisse, Verantwortung und das Bedürfnis nach Kommunikation gibt es überall.“",id:"note-168-job-titles-change",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/168-job-titles-change.jpg?v=703e5436e3"},{q:"„Besonders wichtig ist mir, dass ein offenes Problem nicht wie ein erledigtes aussieht, nur weil meine Schicht endet.“",id:"note-169-care-especially-unclosed",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/169-care-especially-unclosed.jpg?v=59492c0e00"},{q:"„Bei der Entwicklung habe ich verstanden, dass die größte Herausforderung nicht darin lag, eine schöne Seite zu bauen. Sie lag darin, die Information so zu ordnen, dass sie genutzt, geprüft und verbessert werden kann.“",id:"note-170-building-understood-most",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/170-building-understood-most.jpg?v=3c0cab0e81"},{q:"„Wenn das Team eine Kennzahl auf die eine Weise versteht und der Bericht sie auf eine andere berechnet, geht Vertrauen verloren, bevor das erste Ergebnis überhaupt zu sehen ist.“",id:"note-171-if-team-understands",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/171-if-team-understands.jpg?v=71fda00c47"},{q:"„Die Frage ist nicht, ob heute schlechter ist als der Durchschnitt. Das wird an vielen Tagen so sein. Die Frage ist, ob heute schlechter ist, als es die normale Schwankung dieses Prozesses erklärt.“",id:"note-172-question-whether-today",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/172-question-whether-today.jpg?v=83b0970c5b"},{q:"„Im Betrieb ist die Versuchung immer, sofort zur Lösung zu springen. Die Kennzahl ist schlecht, und schon hat jemand eine parat.“",id:"note-173-operations-temptation-always",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/173-operations-temptation-always.jpg?v=61f006fbc4"},{q:"„Man steckt so tief in der Arbeit, dass man den Prozess vielleicht nicht mehr als Prozess sieht.“",id:"note-174-far-inside-work",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/174-far-inside-work.jpg?v=28c5a2f0f2"},{q:"„Ein Versprechen, das nicht von einem selbst abhängt, löst das Problem nicht. Es schiebt es auf den Morgen und macht es schwerer.“",id:"note-175-promise-depend-solve",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/175-promise-depend-solve.jpg?v=462303b79a"},{q:"„Der Fahrer sieht das Problem. Der Disponent sieht seine Wirkung auf die ganze Schicht. Die Führungskraft muss verstehen, warum es das Problem gibt.“",id:"note-176-driver-sees-problem",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/176-driver-sees-problem.jpg?v=d346f4916e"},{q:"„Eine SOP kann man nicht wie ein Dokument behandeln, das einmal geschrieben und dann vergessen wird.“",id:"note-177-sop-cannot-treated",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/177-sop-cannot-treated.jpg?v=741f705d3f"},{q:"„Es ist nicht immer gut, wenn eine Führungskraft zu der Person wird, die alles löst.“",id:"note-178-always-good-leader",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/178-always-good-leader.jpg?v=cafeda6482"},{q:"„Ein Briefing verliert seinen Wert, wenn es bei den Zahlen stehen bleibt.“",id:"note-179-briefing-loses-value",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/179-briefing-loses-value.jpg?v=f46bc99551"},{q:"„Innerhalb eines Teams ist meist klar, wer was macht. Es gibt einen Verantwortlichen, einen Standard, einen Rhythmus. Aber Arbeit bleibt selten in einem einzigen Team.“",id:"note-180-inside-team-usually",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/180-inside-team-usually.jpg?v=770200df4c"},{q:"„Wenn wir nur auf die Person schauen, riskieren wir, einen Prozess unangetastet zu lassen, der dasselbe Problem wieder hervorbringen wird.“",id:"note-181-if-look-only",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/181-if-look-only.jpg?v=24f8d25ae0"},{q:"„Eine Führungskraft muss fehlendes fachliches Können von einer Kommunikationshürde unterscheiden. Es sind zwei verschiedene Probleme, und sie brauchen verschiedene Lösungen.“",id:"note-182-manager-tell-lack",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/182-manager-tell-lack.jpg?v=b812ea9139"},{q:"„Wenn der Prozess nicht als klarer Weg aufgeschrieben ist, lebt er in der Person, die ihn jeden Tag macht.“",id:"note-183-when-process-written",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/183-when-process-written.jpg?v=55958a2563"},{q:"„Wenn eine Information spät ankommt, ist die Verspätung selbst ein Signal. Das Problem hatte Zeit zu wachsen, bevor man davon erfährt.“",id:"note-184-when-information-arrives",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/184-when-information-arrives.jpg?v=4f885e7c87"},{q:"„Auf dem Papier gab es eine Reserve. In der Praxis war die Reserve schon vergeben.“",id:"note-185-paper-there-was",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/185-paper-there-was.jpg?v=a860bc37fa"},{q:"„Ein gutes Dokument ist nützlich. Aber allein garantiert es nicht, dass der Prozess richtig befolgt wird.“",id:"note-186-good-document-useful",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/186-good-document-useful.jpg?v=6b6087f901"},{q:"„Wenn ein Problem in Eile gelöst wird, ist der Ort das Erste, was vergessen wird.“",id:"note-187-when-problem-solved",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/187-when-problem-solved.jpg?v=6e2af06ab8"},{q:"„Eine Korrektur, die sich wiederholt, ist keine Korrektur. Sie ist ein Fehler im System, den niemand gemeldet hat.“",id:"note-188-correction-repeats-correction",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/188-correction-repeats-correction.jpg?v=3e002b040a"},{q:"„Eine rote Zahl ist nicht das, was vor Ort passiert. Sie ist ein Bericht darüber, und ein Bericht hat ein Alter.“",id:"note-189-red-number-report",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/189-red-number-report.jpg?v=82ba131224"},{q:"„Die rote Farbe ist ein Signal zum Prüfen. Sie ist keine Diagnose.“",id:"note-190-signal-not-diagnosis",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/190-signal-not-diagnosis.jpg?v=73bf041db1"},{q:"„Eine rote Zahl sagt Ihnen, wohin Sie schauen müssen. Sie sagt Ihnen nicht, was jetzt dort ist. Der Abstand zwischen beidem ist das Alter der Zahl, und den zu kennen ist Ihre Aufgabe.“",id:"note-191-where-to-look",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/191-where-to-look.jpg?v=817374fb93"},{q:"„Der Status im System und die ganze Geschichte eines Problems sind nicht dasselbe.“",id:"note-192-status-not-history",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/192-status-not-history.jpg?v=abffa5b622"},{q:"„Das System plant die Tour mit den Daten, die es hat. Der Fahrer fährt sie unter den Bedingungen, die er hat. Keiner hat das Ganze ohne den anderen.“",id:"note-193-system-plans-tour",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/193-system-plans-tour.jpg?v=fed60ce93d"},{q:"„Ein erfahrener Fahrer sollte nicht die dauerhafte Korrektur eines Systems sein, das nicht lernt.“",id:"note-194-experienced-driver-should",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/194-experienced-driver-should.jpg?v=a76bb5b7ba"},{q:"„Problematisch ist nicht nur, wenn das System die Tour nicht kennt. Problematisch ist, wenn die Organisation nicht von den Menschen lernt, die sie jeden Tag fahren.“",id:"note-195-problem-system-know",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/195-problem-system-know.jpg?v=672b2c5fef"},{q:"„Die Tour, die der Fahrer nicht versteht, ist manchmal ein Fehler des Plans, manchmal etwas, das ihm niemand erklärt hat. Den Unterschied erkennt man nur, wenn jemand zuhört, es prüft und aufschreibt.“",id:"note-196-tour-driver-understand",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/196-tour-driver-understand.jpg?v=7a6deeab0c"},{q:"„Eine korrekte Erfassung beweist nicht immer, dass der physische Prozess richtig abgeschlossen wurde.“",id:"note-197-accurate-record-always",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/197-accurate-record-always.jpg?v=e7f0e9889c"},{q:"„Der Scanner ist Zeuge einer Handlung. Ein Urteil verlangt, den ganzen Prozess zu verstehen.“",id:"note-198-scanner-witness-action",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/198-scanner-witness-action.jpg?v=2dd5312e62"},{q:"„Das System sagt Ihnen, was erfasst wurde. Die Führungskraft muss verstehen, was passiert ist. Zwischen beidem liegt der Prozess, und dort wird die Arbeit gemacht.“",id:"note-199-system-tells-been",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/199-system-tells-been.jpg?v=b4cfa1b0dd"},{q:"„Zwei Berichte mit zwei verschiedenen Zahlen bedeuten nicht, dass einer falsch liegt. Sie bedeuten, dass Sie wissen müssen, was jeder zählt.“",id:"note-200-two-reports-two",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/200-two-reports-two.jpg?v=b9262d2c9e"},{q:"„Dass ein Bericht erzeugt wurde, bedeutet nicht automatisch, dass jede operative Angelegenheit erledigt ist.“",id:"note-201-generating-report-automatically",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/201-generating-report-automatically.jpg?v=9c69d2e19f"},{q:"„KI kann mir helfen, einen Bericht klarer zu schreiben. Sie darf nicht selbst entscheiden, was wahr ist.“",id:"note-202-ai-help-me",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/202-ai-help-me.jpg?v=2f6acd816c"},{q:"„Ein Bericht soll dem Menschen helfen, die Wirklichkeit zu verstehen, nicht die Prüfung der Wirklichkeit ersetzen.“",id:"note-203-report-should-help",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/203-report-should-help.jpg?v=2bdb2dc974"},{q:"„Die Maschine kann den Bericht schreiben. Die Verantwortung für das, was der Bericht sagt, muss beim Menschen bleiben.“",id:"note-204-machine-write-report",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/204-machine-write-report.jpg?v=0c5f68d6fb"},{q:"„Wenn viele Prozesse von einem System abhängen, wirkt sich seine Unterbrechung nicht nur darauf aus, wie Menschen arbeiten, sondern auch darauf, wie sie lernen.“",id:"note-205-many-processes-depend",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/205-many-processes-depend.jpg?v=f38420d2fa"},{q:"„Die Rückkehr des Systems ist nicht das Ende des Vorfalls.“",id:"note-206-system-coming-back",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/206-system-coming-back.jpg?v=be3afacd7a"},{q:"„Ein vorbereiteter Betrieb tut nicht so, als würde das System nie stillstehen. Er weiß, wie er Verantwortung und Kontinuität der Arbeit bewahrt, wenn das System stillsteht.“",id:"note-207-prepared-operation-pretends",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/207-prepared-operation-pretends.jpg?v=0f630e3b5b"},{q:"„Wenn das System stillsteht, merken Sie, wie viel Ihrer Arbeit davon abhängt und wie gut Sie vorbereitet sind, weiterzumachen.“",id:"note-208-system-stops-realise",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/208-system-stops-realise.jpg?v=0d196c7a00"},{q:"„Ein neues System wird nicht dadurch Teil der Arbeit, dass es installiert ist, sondern dadurch, dass die Menschen es verstehen, wissen, wie man es benutzt, und wissen, was zu tun ist, wenn es ihnen nicht hilft.“",id:"note-209-new-system-become",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/209-new-system-become.jpg?v=830fc9d65a"},{q:"„Die Schwierigkeit eines neuen Systems liegt nicht nur darin, zu wissen, wo man klickt, sondern darin, die richtige Information in dem Moment zu finden, in dem man sie braucht.“",id:"note-210-difficulty-new-system",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/210-difficulty-new-system.jpg?v=a3b6ffca9d"},{q:"„Die Installation verändert das System. Schulung, Kommunikation und die tägliche Erfahrung verändern die Art, wie Menschen arbeiten.“",id:"note-211-installation-changes-system",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/211-installation-changes-system.jpg?v=92ac0d49bc"},{q:"„Wenn ein Mitarbeiter ein Werkzeug baut, um die Arbeit leichter zu machen, zeigt er vielleicht eine Lücke in der Art, wie die Organisation Information verteilt.“",id:"note-212-employee-builds-tool",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/212-employee-builds-tool.jpg?v=9679c3b728"},{q:"„Ein nützliches Werkzeug wird erst dann zum Werkzeug des Teams, wenn es korrekt und aktuell ist, für den Zweck freigegeben, für den man es nutzt, und sicher für die Informationen, die es verarbeitet.“",id:"note-213-useful-tool-becomes",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/213-useful-tool-becomes.jpg?v=c40b68adba"},{q:"„Ein kleines Werkzeug kann ein großes Problem lösen. Aber um Teil der Arbeit zu werden, muss es mehr sein als das Projekt der Person, die es gebaut hat.“",id:"note-214-small-tool-solve",d:"13. Oktober 2026",iso:"2026-10-13",img:"/media/notes/de/214-small-tool-solve.jpg?v=c219fd169f"},{q:"„Eindämmung verschafft Ihnen Zeit. Die Ursache verschafft sie Ihnen nicht. Ein 8D, das bei der Eindämmung stehen bleibt, hat das Problem nur aus dem Blick des Kunden geschoben.“",id:"note-215-containment-buys-time",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/215-containment-buys-time.jpg?v=9882f882e6"},{q:"„Jeder Fehler, den ein Kunde gesehen hat, hat zwei Ursachen: warum er entstanden ist und warum ihn niemand aufgehalten hat, bevor er hinausging. Ein 8D, das nur die erste behebt, lässt den Escape Point offen.“",id:"note-216-every-defect-customer",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/216-every-defect-customer.jpg?v=fd81683f2a"},{q:"„Eine Gefährdungsbeurteilung, die für den Prüfer geschrieben wird, schützt das Papier. Eine, die mit den Menschen geschrieben wird, die die Arbeit machen, schützt die Menschen.“",id:"note-217-risk-assessment-written",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/217-risk-assessment-written.jpg?v=3bc2b751d9"},{q:"„Ein Warnschild ist die letzte Verteidigungslinie, nicht die erste. Beseitigen Sie die Gefahr, bevor Sie von Menschen verlangen, vorsichtig mit ihr zu sein.“",id:"note-218-warning-sign-last",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/218-warning-sign-last.jpg?v=d0b7184d89"},{q:"„Eine Strategie, die niemand in der Halle erklären kann, ist keine Strategie. Sie ist eine Folie.“",id:"note-219-strategy-nobody-floor",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/219-strategy-nobody-floor.jpg?v=818186b181"},{q:"„Ziele, die nur nach unten wandern, kommen als Ausreden zurück. Ziele, die hin- und hergespielt werden, kommen als Zusagen zurück. Genau dafür ist Catchball da.“",id:"note-220-goals-only-travel",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/220-goals-only-travel.jpg?v=8e0bd8ec55"},{q:"„Der größte Teil eines Rüstvorgangs ist Arbeit, die man hätte erledigen können, bevor die Maschine stand.“",id:"note-221-most-changeover-work",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/221-most-changeover-work.jpg?v=804de86f1c"},{q:"„Jede Minute, die Sie aus einem Rüstvorgang herausnehmen, ist eine Minute, die die Linie zurückgibt, ohne eine einzige zusätzliche Person.“",id:"note-222-every-minute-take",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/222-every-minute-take.jpg?v=cceea1275e"},{q:"„Leader Standard Work gibt es aus einem einzigen Grund: damit der Standard des Teams auch den vollsten Tag der Führungskraft übersteht.“",id:"note-223-leader-standard-work",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/223-leader-standard-work.jpg?v=c083413b61"},{q:"„Unterbesetzung ist selten eine Überraschung. Meist ist sie eine Prognose, die niemand in Kapazität übersetzt hat.“",id:"note-224-understaffing-rarely-surprise",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/224-understaffing-rarely-surprise.jpg?v=fbdb823730"},{q:"„Überstunden sind keine Kapazitätsplanung. Sie sind die Rechnung dafür, keine zu haben.“",id:"note-225-overtime-capacity-plan",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/225-overtime-capacity-plan.jpg?v=9544e304f8"},{q:"„Wer den ganzen Bestand mit derselben Sorgfalt zählt, zählt den Bestand, auf den es ankommt, mit zu wenig Sorgfalt.“",id:"note-226-count-all-stock",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/226-count-all-stock.jpg?v=b36851c175"},{q:"„Sicherheitsbestand ist kein Gefühl. Er ist der Preis für die Nachfrage, die Sie nicht vorhersagen können.“",id:"note-227-safety-stock-feeling",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/227-safety-stock-feeling.jpg?v=725de4ea3d"},{q:"„Ein Gast, der in der Lobby wartet, ist selten ein Problem des Housekeepings. Meist ist es ein Zimmerstatus, den niemand aktualisiert hat.“",id:"note-228-guest-waiting-lobby",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/228-guest-waiting-lobby.jpg?v=caac53304f"},{q:"„Wer jeder Zimmerreinigungskraft dieselbe Zahl Zimmer gibt wie gestern, hat nichts geplant: Eine Abreise und ein Bleibezimmer sind nicht dieselbe Arbeit.“",id:"note-229-give-every-attendant",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/229-give-every-attendant.jpg?v=82b0069477"},{q:"„Service Recovery beginnt vor der Entschädigung. Ein Gast, der sich gehört fühlt, verlangt oft weniger als einer, der sich abgefertigt fühlt.“",id:"note-230-service-recovery-begins",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/230-service-recovery-begins.jpg?v=da728fa14b"},{q:"„Die Beschwerde eines Gastes ist nicht abgeschlossen, wenn der Gast die Rezeption verlässt. Sie ist abgeschlossen, wenn Sie zurückrufen und die Antwort Ja lautet.“",id:"note-231-guests-complaint-closed",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/231-guests-complaint-closed.jpg?v=6c0b05335f"},{q:"„Vorbeugende Wartung wirkt immer teuer, bis Sie den Ausfall beziffern, den sie verhindert hat.“",id:"note-232-preventive-maintenance-always",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/232-preventive-maintenance-always.jpg?v=c07dd7f7e9"},{q:"„Eine verschobene Wartung ist keine gesparte Zeit. Sie ist ein Ausfall mit einem Datum, das Sie nicht gewählt haben.“",id:"note-233-postponed-maintenance-job",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/233-postponed-maintenance-job.jpg?v=5b38c9626e"},{q:"„Eine gute Morgenliste sagt Ihnen nicht alles, was passiert ist. Sie sagt Ihnen die drei Dinge, die nicht warten können.“",id:"note-234-good-morning-list",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/234-good-morning-list.jpg?v=4d22c1666f"},{q:"„Standorte nebeneinander zu vergleichen heißt nicht, den schlechtesten zu benennen. Es heißt herauszufinden, was der beste tut und die anderen nicht.“",id:"note-235-comparing-sites-side",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/235-comparing-sites-side.jpg?v=cf45df0ce5"},{q:"„Eine Tafel an der Wand erreicht Menschen, die ein Bildschirm nie erreicht. Das Team, das sich nie anmeldet, liest trotzdem, was auf Papier steht.“",id:"note-236-board-wall-reaches",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/236-board-wall-reaches.jpg?v=95fff5ccc5"},{q:"„Eine Maßnahme ohne Verantwortlichen und ohne Datum ist ein Wunsch, der in einer Besprechung aufgeschrieben wurde.“",id:"note-237-action-without-owner",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/237-action-without-owner.jpg?v=34ce78741a"},{q:"„Layered Audits wirken aus einem Grund: Wenn die Standortleitung denselben Standard prüft wie die Teamleitung, ist der Standard nicht mehr allein das Problem der Teamleitung.“",id:"note-238-layered-audits-work",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/238-layered-audits-work.jpg?v=2e8194196a"},{q:"„Wenn nur eine Person die Aufgabe kann, haben Sie keinen Prozess. Sie haben einen Urlaub, den Sie nicht genehmigen können.“",id:"note-239-if-only-one",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/239-if-only-one.jpg?v=d24e5f2ac7"},{q:"„Ein Zimmer, das ohne Inspektion freigegeben wird, wird trotzdem inspiziert: vom Gast, im ungünstigsten Moment.“",id:"note-240-room-released-without",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/240-room-released-without.jpg?v=c8a6702735"},{q:"„Niemand schreibt das Laufen in die Stellenbeschreibung. Und doch ist das Laufen in vielen Schichten die eigentliche Arbeit.“",id:"note-241-nobody-writes-walking",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/241-nobody-writes-walking.jpg?v=bf795cd27a"},{q:"„Ein Familienunternehmen, das die eigenen Kinder mit Versprechen bezahlt, baut keine Zukunft auf. Es verbraucht sie.“",id:"note-242-family-business-pays",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/242-family-business-pays.jpg?v=81429f3171"},{q:"„Blut kann ein Band sein. Benutzt, um jemandem seinen Lohn zu verweigern, wird es zur Kette.“",id:"note-243-blood-bond-used",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/243-blood-bond-used.jpg?v=fdc31dd5ac"},{q:"„Einen Nachnamen kann man erben. Kompetenz nicht.“",id:"note-244-surname-inherited-competence",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/244-surname-inherited-competence.jpg?v=b92d8e299b"},{q:"„Wenn der Inhaber denjenigen belohnt, der die Führungskraft übergangen hat, rettet er keinen Menschen. Er schaltet das System ab.“",id:"note-245-when-owner-rewards",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/245-when-owner-rewards.jpg?v=a1a42f884f"},{q:"„Pünktlich zu gehen ist kein Mangel an Loyalität. Ungeplante Überstunden jeden Tag sind ein Mangel an Führung.“",id:"note-246-going-home-when",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/246-going-home-when.jpg?v=b2ec7b7bca"},{q:"„Wenn ein guter Mensch geht, hat nicht der Markt versagt. Sondern die Führung.“",id:"note-247-when-good-person",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/247-when-good-person.jpg?v=7da5230e49"},{q:"„Lohn ist kein Brot, das man Ihnen schenkt. Er ist der Preis für die Arbeit, die Sie gegeben haben.“",id:"note-248-wage-bread-given",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/248-wage-bread-given.jpg?v=7186711bdc"},{q:"„Jeden Tag über demselben Fehler zu schwitzen ist keine Hingabe. Es ist ein Prozess, den niemand repariert hat.“",id:"note-249-sweating-every-day",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/249-sweating-every-day.jpg?v=29caccab13"},{q:"„Eine Gehaltserhöhung, die kränkt, kostet mehr als gar keine: Sie sagt den Menschen genau, was ihr Jahr Ihnen wert war.“",id:"note-250-pay-rise-insults",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/250-pay-rise-insults.jpg?v=b0db3f838e"},{q:"„Wenn die Personalabteilung den Menschen vergisst, bleibt nur noch der Stempel.“",id:"note-251-when-human-resources",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/251-when-human-resources.jpg?v=654321e34f"},{q:"„Der Lärm der Bewegung ist kein Fortschritt. Eine Führungskraft, die beschäftigt aussehen muss, hat meist aufgehört, auf die Arbeit zu schauen.“",id:"note-252-noise-motion-progress",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/252-noise-motion-progress.jpg?v=5492269473"},{q:"„Eine Maschine, die die ganze Schicht läuft, ist nicht unbedingt eine Maschine, die produziert. Die OEE zeigt Ihnen den Unterschied in Minuten.“",id:"note-253-machine-runs-all",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/253-machine-runs-all.jpg?v=93ef36207f"},{q:"„Der größte Verlust ist selten der Ausfall, an den sich alle erinnern. Es sind die kleinen Stopps, die niemand aufschreibt.“",id:"note-254-biggest-loss-rarely",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/254-biggest-loss-rarely.jpg?v=b764ce760e"},{q:"„Ein Fischgrätdiagramm, das eine einzige Person ausfüllt, ist eine Vermutung mit einem Diagramm drumherum.“",id:"note-255-fishbone-filled-by",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/255-fishbone-filled-by.jpg?v=8b7f4bda7b"},{q:"„Eine FMEA stellt die unbequeme Frage, solange die Antwort noch billig ist: Wie kann dieser Schritt scheitern?“",id:"note-256-fmea-asks-uncomfortable",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/256-fmea-asks-uncomfortable.jpg?v=4cbb83e584"},{q:"„Eine Linie lässt sich nicht mit Meinungen darüber austakten, wie lange eine Arbeit dauert. Eine Stoppuhr ist gerechter als ein Gefühl.“",id:"note-257-cannot-balance-line",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/257-cannot-balance-line.jpg?v=a3eecd26d5"},{q:"„Der Takt ist kein Ziel, zu dem man Menschen antreibt. Er ist der Rhythmus, den die Nachfrage vorgibt.“",id:"note-258-takt-target-push",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/258-takt-target-push.jpg?v=13822ff498"},{q:"„In den meisten Wertströmen ist die Arbeit selbst schnell. Es ist das Warten zwischen den Schritten, das den Auftrag verspätet.“",id:"note-259-most-value-streams",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/259-most-value-streams.jpg?v=24b1a533dc"},{q:"„Ein Kernpunkt ohne Begründung ist eine Regel, die am ersten vollen Tag fallen gelassen wird.“",id:"note-260-key-point-without",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/260-key-point-without.jpg?v=10798eea52"},{q:"„Wenn das Problem nicht auf ein A3 passt, haben Sie es noch nicht verstanden. Sie haben es nur gesammelt.“",id:"note-261-if-problem-fit",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/261-if-problem-fit.jpg?v=be7e47d06e"},{q:"„Eine Verbesserungsidee, die drei Monate auf eine Antwort wartet, bringt dem Team bei, keine Ideen mehr zu haben.“",id:"note-262-improvement-idea-waits",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/262-improvement-idea-waits.jpg?v=f2de9702d5"},{q:"„Ein Kaizen-Event bewährt sich nicht am letzten Tag des Workshops. Es bewährt sich beim 30-Tage-Check, wenn niemand mehr hinschaut.“",id:"note-263-kaizen-event-proven",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/263-kaizen-event-proven.jpg?v=f64dd1e1b0"},{q:"„Ein Beinahe-Unfall ist eine kostenlose Lektion. Der nächste kommt vielleicht mit der Rechnung.“",id:"note-264-near-miss-free",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/264-near-miss-free.jpg?v=38b9207cd6"},{q:"„Ein Red Tag ist keine Strafe für den Gegenstand. Er ist eine Frage: Verdient er seinen Platz hier noch?“",id:"note-265-red-tag-punishment",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/265-red-tag-punishment.jpg?v=249111ed78"},{q:"„Die Auslastung kann hoch sein und die Nacht trotzdem Geld verlieren. Der RevPAR sagt Ihnen, ob die Zimmer verdient haben, was sie konnten.“",id:"note-266-occupancy-high-night",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/266-occupancy-high-night.jpg?v=6fd15ee15e"},{q:"„Im Night Audit treffen die Versprechen des Tages auf die Buchungen des Tages. Jede Lücke, die nachts gefunden wird, ist billiger als eine, die der Gast findet.“",id:"note-267-night-audit-where",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/267-night-audit-where.jpg?v=c9bc13ea2b"},{q:"„Fundsachen sind ein kleines Register mit einem großen Versprechen: Was ein Gast vergessen hat, haben wir nicht vergessen.“",id:"note-268-lost-property-small",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/268-lost-property-small.jpg?v=acb34a1ab6"},{q:"„Ein Huddle, der nur die Zahlen von gestern vorliest, ist ein Bericht. Ein Huddle, der die eine Maßnahme für heute beschließt, ist Führung.“",id:"note-269-huddle-only-reads",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/269-huddle-only-reads.jpg?v=98d69e84db"},{q:"„Ein Wochenbericht sollte mit einer Entscheidung enden, nicht mit einer Zusammenfassung. Sonst wurde er zum Ablegen geschrieben, nicht zum Lesen.“",id:"note-270-weekly-report-should",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/270-weekly-report-should.jpg?v=e47c36f7fc"},{q:"„Zehn laufende Projekte sind oft null abgeschlossene. Ein Portfolio zeigt Ihnen, welches Sie stoppen sollten.“",id:"note-271-ten-projects-progress",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/271-ten-projects-progress.jpg?v=832f4445bf"},{q:"„Ein Prozess kann beherrscht sein und trotzdem nicht fähig. Stabil und gut genug sind zwei verschiedene Fragen.“",id:"note-272-process-control-still",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/272-process-control-still.jpg?v=a8dd3c3199"},{q:"„Ein Lebenslauf ist keine Liste der Stellen, die Sie hatten. Er ist der Beweis für die Probleme, die Sie gelöst haben.“",id:"note-273-cv-list-jobs",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/273-cv-list-jobs.jpg?v=f8dcb31c73"},{q:"„Ein Anschreiben, das an jedes Unternehmen gehen könnte, wird von keinem gelesen.“",id:"note-274-cover-letter-could",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/274-cover-letter-could.jpg?v=afdb25efd8"},{q:"„Wenn ein Prozess nur funktioniert, weil Menschen ihn ständig reparieren, funktioniert nicht der Prozess. Die Menschen funktionieren.“",id:"note-275-when-process-works",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/275-when-process-works.jpg?v=c5e7e2c148"},{q:"„Schnell beheben ist nicht schnell lernen. Dieselbe Korrektur zweimal ist derselbe Fehler zweimal.“",id:"note-276-fixing-fast-learning",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/276-fixing-fast-learning.jpg?v=3698298b85"},{q:"„Ein Workaround ist eine Nachricht aus der Halle. Bestrafen Sie ihn, und die Nachricht hört auf. Das Problem nicht.“",id:"note-277-workaround-message-from",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/277-workaround-message-from.jpg?v=e549598629"},{q:"„Die Kollegin, die es immer weiß, ist keine Lösung. Sie ist eine Abhängigkeit, die niemand aufgeschrieben hat.“",id:"note-278-colleague-who-always",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/278-colleague-who-always.jpg?v=3c3da1734c"},{q:"„Derselbe Mensch, den man hier faul nennt, wird im Ausland zum Musterangestellten. Geändert hat sich nicht der Mensch, sondern das System.“",id:"note-279-same-person-called",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/279-same-person-called.jpg?v=f535aae273"},{q:"„Die Faulheit eines Volkes zu beschuldigen ist das bequemste Alibi, das eine gescheiterte Führung finden kann.“",id:"note-280-blaming-laziness-people",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/280-blaming-laziness-people.jpg?v=dc7e9f2ac8"},{q:"„Wenn Ihr Notfall um Mitternacht meine Pflicht ist, dann ist mein Lohn keine Frage für die Sprechzeiten.“",id:"note-281-if-your-emergency",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/281-if-your-emergency.jpg?v=3ec9b97178"},{q:"„Ein Lohn kauft Ihre Arbeit, nicht Ihre Freizeit. Ein Telefon, das immer an sein muss, ist unbezahlte Arbeit.“",id:"note-282-wage-buys-your",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/282-wage-buys-your.jpg?v=9e8df05e63"},{q:"„Zwei Tage Einarbeitung sind kein Onboarding. Sie sind ein Ultimatum mit einem Lächeln.“",id:"note-283-two-days-training",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/283-two-days-training.jpg?v=5417ba893e"},{q:"„Wenn ein Geschäft auf dem Gedächtnis des Inhabers läuft, ist jeder neue Mensch zum Scheitern verurteilt.“",id:"note-284-when-shop-runs",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/284-when-shop-runs.jpg?v=372489cade"},{q:"„Lohn zu zahlen ist keine Wohltätigkeit. Es ist der Vertrag, den der Inhaber unterschrieben hat, als er jemanden eingestellt hat.“",id:"note-285-paying-wages-charity",d:"25. Oktober 2026",iso:"2026-10-25",img:"/media/notes/de/285-paying-wages-charity.jpg?v=4f7abc8df9"},{q:"„Wo alles dringend ist, ist nichts wichtig. Ständige Eile ist die bequemste Tarnung für fehlende Planung.“",id:"note-286-everything-urgent-nothing",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/286-everything-urgent-nothing.jpg?v=8dbec8a248"},{q:"„Die Jagd auf den Schuldigen ist keine Gerechtigkeit. Wenn Strafe die Ursachenanalyse ersetzt, ist derselbe Fehler für morgen schon gebucht.“",id:"note-287-hunting-culprit-not",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/287-hunting-culprit-not.jpg?v=b55f31a386"},{q:"„Angesichts offenen Unrechts gibt es keine Neutralität. Schweigen ist kein Frieden. Es ist eine leise Stimme für den, der andere mit Füßen tritt.“",id:"note-288-silence-not-peace",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/288-silence-not-peace.jpg?v=07696be159"},{q:"„Kosten verschwinden nicht, nur weil das Unternehmen nicht mehr dafür zahlt. Sie wechseln die Abteilung und landen bei jemandem, der nicht im Raum war.“",id:"note-289-cost-does-not",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/289-cost-does-not.jpg?v=54b077b3f0"},{q:"„Eine Führungskraft schuldet nicht jeder getroffenen Entscheidung Treue. Nur der besten Entscheidung, die mit der Wahrheit von heute möglich ist.“",id:"note-290-loyal-best-decision",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/290-loyal-best-decision.jpg?v=d9c3a277af"},{q:"„Ihr Wert liegt nicht darin, wie unersetzlich Sie sich durch verborgenes Wissen machen. Er liegt darin, wie unabhängig Sie die Menschen um sich machen.“",id:"note-291-hiding-knowledge-value",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/291-hiding-knowledge-value.jpg?v=7f28389fb0"},{q:"„Macht kann Menschen zwingen, Ihnen Antworten zu geben. Sie kann sie nicht zwingen, Ihnen die Wahrheit zu sagen, wenn Sie sie gelehrt haben, sie zu fürchten.“",id:"note-292-power-forces-answers",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/292-power-forces-answers.jpg?v=f811656775"},{q:"„Ein grüner Bericht belegt, dass das Ziel erreicht wurde. Er belegt nicht, dass der Weg dorthin richtig war. Fragen Sie, was übersehen werden musste.“",id:"note-293-green-report-proves",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/293-green-report-proves.jpg?v=df809247e4"},{q:"„Ein Problem wird nicht zur Verantwortung aller, nur weil alle darüber gesprochen haben. Ein Meeting ohne Verantwortlichen lässt die Entscheidung verwaist zurück.“",id:"note-294-problem-discussed-many",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/294-problem-discussed-many.jpg?v=59ba0416b0"},{q:"„Eine Maschine kann eine Stunde sparen. Nur der Mensch entscheidet, ob daraus mehr Wert, mehr Freiheit oder schlicht mehr Arbeit wird.“",id:"note-295-machine-saves-hour",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/295-machine-saves-hour.jpg?v=28a5086738"},{q:"„Wenn die, die entscheiden, vor den Folgen geschützt sind, ist der Fehler keine Möglichkeit mehr. Er ist eine Gewissheit.“",id:"note-296-shielded-from-consequences",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/296-shielded-from-consequences.jpg?v=5f680c16ff"},{q:"„Wer Zusammenarbeit nicht über Abläufe aufbauen kann, baut Clans über Intrigen. Ein gespaltenes Team hat nie Zeit, die Leere an der Spitze zu sehen.“",id:"note-297-divided-team-never",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/297-divided-team-never.jpg?v=3fa6622fca"},{q:"„Fünf Worte prüfen den Charakter einer Führungskraft: Ich gab den falschen Befehl. Gesagt vor den Leuten, nicht hinter ihnen versteckt.“",id:"note-298-wrong-order-stand",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/298-wrong-order-stand.jpg?v=6ba35e8532"},{q:"„Die moralische Prüfung eines Profis findet nicht unter Applaus statt. Sie findet allein am Arbeitsplatz statt, wo der bequeme Kompromiss jede Sekunde lockt.“",id:"note-299-moral-test-floor",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/299-moral-test-floor.jpg?v=3b28a506ea"},{q:"„Ungerechtigkeit beginnt nicht nur, wenn jemand weniger bekommt. Manchmal beginnt sie, wenn von ihm weit mehr verlangt wird und alle beteuern, niemand sei anders behandelt worden.“",id:"note-300-injustice-asking-more",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/300-injustice-asking-more.jpg?v=a8a35ea593"},{q:"„Regeln, die an der Tür des Managers enden, schützen die Organisation nicht mehr vor Willkür. Sie schützen die Willkür des Managers vor der Organisation.“",id:"note-301-rules-manager-door",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/301-rules-manager-door.jpg?v=5e10273085"},{q:"„Wer nie Nein sagen kann, ist nicht loyal. Er hat nur keine Grenzen, und wo die Grenzen eines Menschen enden, beginnt die Ausbeutung.“",id:"note-302-never-saying-no",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/302-never-saying-no.jpg?v=752799ab76"},{q:"„Der traurigste Erfolg ist der, den man so hingebungsvoll aufbaut, dass beim ersten Aufblicken ein Teil des Lebens, das er füllen sollte, ohne einen vergangen ist.“",id:"note-303-saddest-success-built",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/303-saddest-success-built.jpg?v=3ec88293ca"},{q:"„Der schwerste Ruhm im Betrieb ist ein Ergebnis, das niemand bemerkt, weil nichts schiefgehen musste, um Ihre Arbeit sichtbar zu machen.“",id:"note-304-glory-nothing-went",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/304-glory-nothing-went.jpg?v=d145758e7b"},{q:"„Eine Organisation kann ihre Stabilität jahrelang mit der Fähigkeit eines Einzelnen verwechseln, die Schwächen aller anderen abzufangen. Das ist keine Stärke, sondern ein stillschweigend hingenommenes Versagen.“",id:"note-305-stability-one-person",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/305-stability-one-person.jpg?v=887d9d23f0"},{q:"„Die Führungskraft, die die Wahrheit nicht kennt, hat es oft selbst so gewollt: Entscheidung für Entscheidung hat sie die Wahrheit zur Feindin ihres Büros erklärt.“",id:"note-306-truth-enemy-office",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/306-truth-enemy-office.jpg?v=4f0a07f85d"},{q:"„Wenn die Personalabteilung aufhört, den Standard zu verteidigen, und anfängt, die Willkür abzustempeln, ist sie keine Führungsfunktion mehr. Sie ist Komplizin.“",id:"note-307-hr-notary-arbitrary",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/307-hr-notary-arbitrary.jpg?v=48b7a06884"},{q:"„Ein Inhaber, der seine eigenen Leute an Wissen, Autorität und Ego übertreffen will, verteidigt nicht die Firma. Er zerstört seine eigene Investition.“",id:"note-308-owner-outdo-staff",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/308-owner-outdo-staff.jpg?v=7e2a2d6724"},{q:"„Sie können nicht jeden Tag Gift in den Dorfbrunnen gießen und sich dann mit den Nachbarn wundern, warum das Wasser die Kinder krank macht.“",id:"note-309-poison-village-well",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/309-poison-village-well.jpg?v=592e9b9af8"},{q:"„Regeln zeigen, wo unsere Verantwortung endet. Innerhalb dieser Grenzen zeigt das Urteil, wie ernst wir den Menschen nehmen. Ein Regelwerk darf nicht das Gewissen dessen schließen, der es anwendet.“",id:"note-310-rules-judgement-person",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/310-rules-judgement-person.jpg?v=f01724c024"},{q:"„Ein Team kann zerbrechen, nicht an einem schwachen Mitarbeiter, sondern wenn alle lernen, dass sie weniger wert sein müssen, um ein Talent zu halten.“",id:"note-311-talent-worth-less",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/311-talent-worth-less.jpg?v=030dce44f0"},{q:"„Macht korrumpiert den Menschen nicht. Sie zieht den Vorhang vor dem beiseite, was schon da war, bevor er sich auf den Stuhl setzte.“",id:"note-312-power-pulls-curtain",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/312-power-pulls-curtain.jpg?v=665c717258"},{q:"„In der Opferrolle liegt eine gefährliche Bequemlichkeit: Wenn an allem die anderen schuld sind, sind Sie vom Handeln befreit.“",id:"note-313-comfort-of-victim",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/313-comfort-of-victim.jpg?v=7156fd8a0b"},{q:"„Chaos mit Leidenschaft und Ordnung mit Trägheit zu verwechseln ist das deutlichste Zeichen eines Unternehmens, das sich selbst nicht einschätzen kann.“",id:"note-314-chaos-for-passion",d:"1. November 2026",iso:"2026-11-01",img:"/media/notes/de/314-chaos-for-passion.jpg?v=0d40c5d8d6"}];